212	    /// Sync paged attention metadata to GPU.
213	    ///
214	    /// `padded_bs` >= `views.len()`: padding slots (if any) point to the
215	    /// reserved padding page with seq_len=1 so FlashInfer accesses valid memory.
216	    pub(crate) fn sync_paged_views(
217	        &mut self,
218	        ctx: &DeviceContext,
219	        views: &[KvView],
220	        padded_bs: usize,
221	    ) -> Result<()> {
222	        let real_bs = views.len();
223	        debug_assert!(padded_bs >= real_bs);
224	
225	        let mut all_page_indices = Vec::new();
226	        let mut indptr = vec![0i32];
227	        let mut last_page_lens = Vec::with_capacity(padded_bs);
228	        let mut chunk_sizes = Vec::with_capacity(padded_bs);
229	
230	        for view in views {
231	            all_page_indices.extend_from_slice(view.page_indices());
232	            indptr.push(all_page_indices.len() as i32);
233	            last_page_lens.push(view.last_page_len() as i32);
234	            chunk_sizes.push(view.seq_len() as i32);
235	        }
236	
237	        // Padding slots: 1 page (the padding page), seq_len=1, last_page_len=1.
238	        for _ in real_bs..padded_bs {
239	            all_page_indices.push(self.padding_page_id);
240	            indptr.push(all_page_indices.len() as i32);
241	            last_page_lens.push(1);
242	            chunk_sizes.push(1);
243	        }
244	
245	        let request_indices: Vec<i32> = (0..padded_bs as i32).collect();
246	        let kv_tile_indices = vec![0i32; padded_bs];
247	
248	        anyhow::ensure!(
249	            all_page_indices.len() <= self.page_indices_d.len(),
250	            "Qwen3.5 decode page-index overflow: {} view pages exceed buffer capacity {}",
251	            all_page_indices.len(),
252	            self.page_indices_d.len()
253	        );
254	        ctx.stream
255	            .memcpy_htod(&all_page_indices, &mut self.page_indices_d)?;
256	        ctx.stream.memcpy_htod(&indptr, &mut self.page_indptr_d)?;
257	        ctx.stream
258	            .memcpy_htod(&last_page_lens, &mut self.last_page_len_d)?;
259	        ctx.stream
260	            .memcpy_htod(&chunk_sizes, &mut self.kv_chunk_size_d)?;
261	        ctx.stream
262	            .memcpy_htod(&request_indices, &mut self.request_indices_d)?;
263	        ctx.stream
264	            .memcpy_htod(&kv_tile_indices, &mut self.kv_tile_indices_d)?;
265	
266	        Ok(())
267	    }
268	}
