78	        for _ in 0..max_batch {
79	            slot_states.push(RecurrentState::new(ctx, config, geometry)?);
80	        }
81	        let linear_pointer_tables = {
82	            let mut slot_refs: Vec<&mut RecurrentState> = slot_states.iter_mut().collect();
83	            LinearStatePointerTables::from_recurrent_refs(
84	                ctx,
85	                config,
86	                &mut slot_refs,
87	                max_batch,
88	                "Qwen3.5 graph",
89	            )?
