53	/// Per-layer element counts shared by allocation and reservation:
54	/// (linear layers, f32 state elements, bf16 conv elements).
55	fn per_layer_dims(config: &Config35, geometry: LocalGeometry) -> (usize, usize, usize) {
56	    let num_linear_layers = config.num_hidden_layers - config.num_full_attention_layers();
57	    let state_size = geometry.local_linear_num_value_heads()
58	        * config.linear_key_head_dim
59	        * config.linear_value_head_dim;
60	    let conv_state_size = geometry.local_linear_qkv_dim() * (config.linear_conv_kernel_dim - 1);
61	    (num_linear_layers, state_size, conv_state_size)
62	}
