64	impl RecurrentState {
65	    /// Allocate zeroed recurrent state for all linear attention layers.
66	    pub(crate) fn new(
67	        ctx: &DeviceContext,
68	        config: &Config35,
69	        geometry: LocalGeometry,
70	    ) -> Result<Self> {
71	        let (num_linear_layers, state_size, conv_state_size) = per_layer_dims(config, geometry);
72	
73	        let mut layers = Vec::with_capacity(num_linear_layers);
74	        for _ in 0..num_linear_layers {
75	            let state: CudaSlice<f32> = ctx
76	                .stream
77	                .alloc_zeros(state_size)
78	                .map_err(|e| anyhow::anyhow!("Alloc recurrent state failed: {}", e))?;
79	            layers.push(LayerRecurrentState {
80	                state,
81	                conv_state: DeviceVec::zeros(ctx, conv_state_size)?,
82	            });
83	        }
84	
85	        Ok(Self { layers, seq_len: 0 })
86	    }
87	
88	    /// Copy one complete target-model recurrent state into this allocation.
89	    pub(crate) fn copy_from(&mut self, ctx: &DeviceContext, src: &Self) -> Result<()> {
90	        anyhow::ensure!(
91	            self.layers.len() == src.layers.len(),
92	            "Qwen3.5 recurrent copy layer mismatch: dst={}, src={}",
93	            self.layers.len(),
94	            src.layers.len()
95	        );
96	        for (layer_idx, (dst, src)) in self.layers.iter_mut().zip(&src.layers).enumerate() {
97	            ctx.stream
98	                .memcpy_dtod(&src.state, &mut dst.state)
99	                .map_err(|e| anyhow::anyhow!("copy recurrent layer {layer_idx}: {e}"))?;
100	            ctx.stream
101	                .memcpy_dtod(&src.conv_state.data, &mut dst.conv_state.data)
102	                .map_err(|e| anyhow::anyhow!("copy conv state layer {layer_idx}: {e}"))?;
103	        }
104	        self.seq_len = src.seq_len;
105	        Ok(())
106	    }
107	}
