110	    /// Allocate zeroed per-layer tables with room for `capacity` rows. Rows
111	    /// carry no pointers until `refill_from_recurrent_refs` writes them.
112	    pub(crate) fn with_capacity(
113	        ctx: &DeviceContext,
114	        config: &Config35,
115	        capacity: usize,
116	        label: &str,
117	    ) -> Result<Self> {
118	        let num_linear_layers = config.num_hidden_layers - config.num_full_attention_layers();
119	        let mut state_ptrs = Vec::with_capacity(num_linear_layers);
120	        let mut conv_state_ptrs = Vec::with_capacity(num_linear_layers);
121	        for layer_idx in 0..num_linear_layers {
122	            state_ptrs.push(ctx.stream.alloc_zeros::<u64>(capacity).map_err(|e| {
123	                anyhow::anyhow!("alloc {label} linear state pointer table {layer_idx}: {e}")
124	            })?);
125	            conv_state_ptrs.push(ctx.stream.alloc_zeros::<u64>(capacity).map_err(|e| {
126	                anyhow::anyhow!("alloc {label} conv state pointer table {layer_idx}: {e}")
127	            })?);
128	        }
129	        Ok(Self {
130	            state_ptrs,
131	            conv_state_ptrs,
132	            capacity,
133	        })
134	    }
